from openai.lib._parsing import _completions as _c

class Completions:
    def create(self, **kw):
        return None

class AsyncCompletions:
    def stream(self, **kw):
        _c._materialize_input_tools(kw.get("tools"))
        return _Stream()

class _Stream:
    async def __aenter__(self):
        return self
    async def __aexit__(self, *a):
        return None
    def __aiter__(self):
        return self
    async def __anext__(self):
        raise StopAsyncIteration

class Chat:
    def __init__(self):
        self.completions = Completions()

class AsyncChat:
    def __init__(self):
        self.completions = AsyncCompletions()
